import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import { Card, Field } from '@/components/ui'
import { Icon } from '@/design-system/Icon'
import { useSession } from '@/app/session'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope } from '@/db/db'
import { useI18n, type MessageKey } from '@/i18n'
import { fmtDate } from '@/i18n/format'
import type { WeeklySync } from '@/types/domain'
import { previousWeek, weekEnd, weekOf } from './weekOf'
import './weekly.css'

/**
 * The weekly sit-down (REL-03).
 *
 * Five questions, always the same five, always in this order — and the order is
 * the design. "What went well" comes first because a couple that opens with the
 * hard thing has an argument instead of a review. The appreciation is last so
 * the final thing said is a kind one. The middle three move from observation
 * ("what felt heavy") to request ("what would help"), which is the direction a
 * conversation has to travel anyway.
 *
 * Every field is optional and it saves as you go. A form that refuses to save
 * until it is complete is a form people stop opening, and a week where one box
 * got filled is still a week they sat down.
 *
 * Each person writes their own record; `weekOf` pairs them. Nothing merges the
 * two, nothing scores them, and nothing points out that one side is empty.
 */

const QUESTIONS = [
  { field: 'good', label: 'weekly.good', hint: 'weekly.goodHint' },
  { field: 'heavy', label: 'weekly.heavy', hint: 'weekly.heavyHint' },
  { field: 'help', label: 'weekly.help', hint: 'weekly.helpHint' },
  { field: 'appreciation', label: 'weekly.appreciation', hint: 'weekly.appreciationHint' },
  { field: 'priority', label: 'weekly.priority', hint: 'weekly.priorityHint' },
] as const

type QuestionField = (typeof QUESTIONS)[number]['field']

export default function Weekly() {
  const { t, locale } = useI18n()
  const { profile, partner } = useSession()
  const me = profile?.id
  const [week, setWeek] = useState(() => weekOf(new Date()))
  const [draft, setDraft] = useState<Partial<Record<QuestionField, string>>>({})
  const [madeTask, setMadeTask] = useState(false)

  const all = useOwned<WeeklySync>('weekly', me)
  const mine = (all ?? []).find((w) => w.weekOf === week && w.ownerProfileId === me)
  const theirs = partner ? (all ?? []).find((w) => w.weekOf === week && w.ownerProfileId === partner.id) : undefined

  // Reload the boxes when the week changes or the record arrives from Dexie.
  useEffect(() => {
    setDraft({
      good: mine?.good ?? '',
      heavy: mine?.heavy ?? '',
      help: mine?.help ?? '',
      appreciation: mine?.appreciation ?? '',
      priority: mine?.priority ?? '',
    })
    setMadeTask(false)
  }, [mine?.id, week])

  if (!profile || !me) return null

  async function persist(next: Partial<Record<QuestionField, string>>) {
    if (!me) return
    const body = Object.fromEntries(
      QUESTIONS.map((q) => [q.field, next[q.field]?.trim()]).filter(([, v]) => v),
    )
    if (mine) {
      await db.weekly.update(mine.id, { ...body, updatedAt: new Date().toISOString() } as never)
    } else if (Object.keys(body).length > 0) {
      await db.weekly.add({
        // Shared by default: this is a conversation, not a diary. Anything the
        // person wants kept to themselves belongs in a check-in note.
        ...newEnvelope(me, 'C3_relationship', { visibility: 'shared' }),
        kind: 'weekly',
        weekOf: week,
        ...body,
      } as never)
    }
  }

  function onBlur(field: QuestionField) {
    void persist(draft)
    void field
  }

  async function makeTask() {
    const title = draft.priority?.trim()
    if (!title || !me) return
    await db.tasks.add({
      ...newEnvelope(me, 'C2_shared_ops', { visibility: 'shared' }),
      kind: 'task',
      title,
      accountableProfileId: me,
      mentalLoadType: 'both',
      status: 'todo',
    } as never)
    setMadeTask(true)
  }

  const filled = QUESTIONS.filter((q) => (draft[q.field] ?? '').trim().length > 0).length

  return (
    <div className="stack">
      <h1>{t('weekly.title')}</h1>
      <p className="card__hint">{t('weekly.intro')}</p>

      <div className="row row--between weekly__nav">
        <button type="button" className="btn btn--ghost btn--sm" onClick={() => setWeek(previousWeek(week))}>
          <Icon name="chevron-left" size={18} label={t('weekly.prev')} />
        </button>
        <strong aria-live="polite">
          {fmtDate(week, 'd MMM', locale)} – {fmtDate(weekEnd(week), 'd MMM yyyy', locale)}
        </strong>
        <button
          type="button"
          className="btn btn--ghost btn--sm"
          disabled={week >= weekOf(new Date())}
          onClick={() => setWeek(weekOf(new Date()))}
        >
          {t('weekly.thisWeek')}
        </button>
      </div>

      {/* A count, not a score. It says how far through the five you are and
          stops there — no target, no streak, nothing that turns a conversation
          into something you can fail. */}
      <p className="weekly__progress">{t('weekly.progress', { n: filled })}</p>

      <ol className="weekly__list">
        {QUESTIONS.map((q, i) => (
          <li key={q.field}>
            <Card title={`${i + 1}. ${t(q.label as MessageKey)}`} hint={t(q.hint as MessageKey)}>
              <Field label={t(q.label as MessageKey)} hint={t('common.optional')}>
                {(p) => (
                  <textarea
                    {...p}
                    value={draft[q.field] ?? ''}
                    onChange={(e) => setDraft({ ...draft, [q.field]: e.target.value })}
                    onBlur={() => onBlur(q.field)}
                  />
                )}
              </Field>

              {q.field === 'priority' && (draft.priority ?? '').trim() && (
                <button type="button" className="btn btn--soft btn--sm" onClick={() => void makeTask()} disabled={madeTask}>
                  <Icon name={madeTask ? 'check' : 'plus'} size={16} />
                  {madeTask ? t('weekly.taskMade') : t('weekly.makeTask')}
                </button>
              )}

              {theirs?.[q.field] && (
                <div className="weekly__theirs">
                  <p className="weekly__theirsName">{partner?.displayName}</p>
                  <p>{theirs[q.field]}</p>
                </div>
              )}
            </Card>
          </li>
        ))}
      </ol>

      {partner && !theirs && (
        <p className="card__hint">{t('weekly.theirsWaiting', { name: partner.displayName })}</p>
      )}

      <Card title={t('weekly.afterTitle')} icon="tasks" hint={t('weekly.afterHint')}>
        <Link to="/kehidupan" className="btn btn--ghost btn--block">
          <Icon name="tasks" size={18} />
          {t('weekly.openPlans')}
        </Link>
      </Card>
    </div>
  )
}
