import { addDays, format, parseISO, startOfWeek } from 'date-fns'

/**
 * Which week a moment belongs to.
 *
 * Monday, not Sunday: an Indonesian week starts on Monday, and a couple sitting
 * down on Sunday evening is reviewing the week that just ended rather than
 * starting the next one. Getting this backwards would file half of every
 * sit-down under the wrong week and make the two halves of a pair disagree
 * about which week they were even in.
 */
export function weekOf(date: Date | string): string {
  const d = typeof date === 'string' ? parseISO(date) : date
  return format(startOfWeek(d, { weekStartsOn: 1 }), 'yyyy-MM-dd')
}

/** The Monday before this one. */
export function previousWeek(week: string): string {
  return format(addDays(parseISO(week), -7), 'yyyy-MM-dd')
}

/** The Monday after this one. */
export function nextWeek(week: string): string {
  return format(addDays(parseISO(week), 7), 'yyyy-MM-dd')
}

/** Sunday of the given week, for showing a range. */
export function weekEnd(week: string): string {
  return format(addDays(parseISO(week), 6), 'yyyy-MM-dd')
}
